it('zh-cn meridiem round trip vs moment', () => {
  const format = 'YYYY年M月D日Ah点mm分ss秒'
  for (let h = 0; h < 24; h += 1) {
    const s = `2018-05-02 ${String(h).padStart(2, '0')}:02:03`
    const str = dayjs(s).locale('zh-cn').format(format)
    const mstr = moment(s).locale('zh-cn').format(format)
    expect(`${h}: ${str}`).toBe(`${h}: ${mstr}`)
    expect(`${h}: ${dayjs(str, format, 'zh-cn').format('YYYY-MM-DD HH:mm:ss')}`)
      .toBe(`${h}: ${moment(mstr, format, 'zh-cn').format('YYYY-MM-DD HH:mm:ss')}`)
  }
})

it('ja/ko/zh meridiem round trip vs moment', () => {
  const cases = [
    ['ja', 'YYYY年M月D日Ah時mm分ss秒'],
    ['ko', 'YYYY년 M월 D일 Ah시 mm분 ss초'],
    ['zh', 'YYYY年M月D日Ah點mm分ss秒']
  ]
  cases.forEach(([l, format]) => {
    for (let h = 0; h < 24; h += 1) {
      const s = `2018-05-02 ${String(h).padStart(2, '0')}:02:03`
      const str = dayjs(s).locale(l).format(format)
      const mstr = moment(s).locale(l).format(format)
      expect(`${l} ${h}: ${str}`).toBe(`${l} ${h}: ${mstr}`)
      const got = dayjs(str, format, l).format('YYYY-MM-DD HH:mm:ss')
      const want = moment(mstr, format, l).format('YYYY-MM-DD HH:mm:ss')
      if (got !== want) console.log(`DIFF ${l} ${h}: dayjs=${got} moment=${want} str=${str}`)
    }
  })
})
